const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const furnaceCreek = ee.Geometry.Point([-116.8667, 36.4564]);
  const startDate = '2013-06-30';
  const endDate = '2013-07-01';

  // 2. Data Acquisition - ERA5-Land hourly data for air temperature
  let collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(furnaceCreek)
    .select('temperature_2m');

  const collectionSize = collection.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No ERA5-Land data found for this date.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Get maximum temperature across all hours
  const maxTemp = collection.max();

  // 4. Extract temperature value at point
  const result = maxTemp.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: furnaceCreek,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo();

  const tempKelvin = result.temperature_2m;

  // 5. Validation & Conversion
  if (tempKelvin === null || tempKelvin === undefined) {
    console.log("Temperature value is null.");
    console.log("<answer>C3</answer>");
    return;
  }

  const tempCelsius = tempKelvin - 273.15;

  console.log(`Maximum air temperature on 2013-06-30: ${tempCelsius.toFixed(2)}°C (${tempKelvin.toFixed(2)}K)`);
  console.log(`Threshold: 58.00°C`);

  // Check for unrealistic values
  if (tempCelsius < -100 || tempCelsius > 100) {
    console.log("Temperature value outside realistic range.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 6. Final Answer
  if (tempCelsius > 58.0) {
    console.log("Temperature exceeded 58°C.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Temperature did not exceed 58°C.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
